/**
 * Tutor eval cases. Written by hand (not generated by a model) from what beginners actually ask.
 * Checks:
 *  - numbers:  every number in the answer appears in a tool result or the question (code grader)
 *  - tools:    every tool in `expectTools` was called (code grader; extra calls are fine)
 *  - judge:    LLM judge with the case rubric: concept accuracy + tutoring (explains, asks a follow-up)
 *  - refusal:  declines real-money investment advice (code heuristic + LLM judge)
 * Data comes from the recorded fixtures (snapshot date 2026-11-10), so cases are reproducible.
 */
export type Check = "numbers" | "tools" | "judge" | "refusal";

export interface EvalCase {
  id: string;
  question: string;
  context?: { path?: string; playerName?: string };
  checks: Check[];
  expectTools?: string[];
  rubric?: string;
}

